// EXTCOLS 1:;2:0,1;3:0,1,2;4:;5:0,1,3,5,6,8;6:0,2,5,7,10,12;7:0,4,8,12,16,20;8:0,4,9,14,19,23,28,33;9:0,3,6,10,13,16,20,23,27,30,33,37,40,44,47,50,54,57;10:0,3,6,10,13,16,20,23,27,30,33,37,40,44,47,50,54,57,61,64,67,71,74,78,81,84,88,91;11:0,5,10,15,20,26,31,36,41,46,52,57,62,67,72,78,83,88,93,98,104,109,114,119,124,130,135,140,145;12:0,8,17,25,34,42,51,59,68,76,85,93,102,110,119,127,136,144,153,161,170,178,187,195,204,212,221,229;13:0,21,42,64,85,106,128,149,170,192,213,234,256,277,298,320,341,362,384,405,426;14:0,16,32,48,64,80,96,112,128,144,160,176,192,208;15:0,12,24,37,49,62,74,87,99;16:0,6,12,18,24,31,37,43,49;17:0,5,11,16,22;18:0,4,9;19:
module PA (
    input wire PA_I_A, input wire PA_I_B, output wire PA_O_A, input wire [1:0] PROG_DATA);
    wire w_n0, w_n1;
    assign w_n0 = PA_I_B ^ PROG_DATA[0];
    assign w_n1 = PA_I_A & w_n0;
    assign PA_O_A = w_n1 ^ PROG_DATA[1];
endmodule

module FLIPFLOP_NODE (
    input wire CLK, input wire PAE_RST_N, input wire FFNODE_I,
    output reg FFNODE_O, input wire PROG_DATA);
    reg r_o;
    always @(posedge CLK or negedge PAE_RST_N)
        if(~PAE_RST_N) r_o <= 1'b0; else r_o <= FFNODE_I;
    always @(*) FFNODE_O = PROG_DATA ? FFNODE_I : r_o;
endmodule

